// Shared Earthbound rules. The app supplies observed wallet snapshots only;
// no random size variation is generated by the renderer. Sizes are raster pixels.
export const MAX_HOLDER_BALANCES=128;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const finite=v=>typeof v==='number'&&Number.isFinite(v);
const decimal=/^(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i;

export function normalizeHolderBalances(value){
  if(!Array.isArray(value)||value.length>MAX_HOLDER_BALANCES)return [];
  const result=[],ids=new Set();
  for(let i=0;i<value.length;i++){
    const record=value[i],balance=typeof record==='number'?record:record?.balance;
    const id=typeof record?.id==='string'?record.id.trim():String(i+1);
    if(!finite(balance)||balance<0||!id||id.length>512||ids.has(id))return [];
    ids.add(id);
    if(balance>0)result.push({id,balance});
  }
  return result;
}

export function parseHolderBalances(text){
  const source=String(text??'').trim();
  if(!source)return {balances:[],error:''};
  try{
    let rows;
    if(source.startsWith('[')){
      const values=JSON.parse(source);
      if(!Array.isArray(values))throw Error('Use a JSON array of balances or {id, balance} records.');
      rows=values.map((v,i)=>typeof v==='number'?{id:String(i+1),balance:v}:v);
    }else{
      let lines=source.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
      const hasHeader=/^(?:wallet|address|id)[,\t ]+balance$/i.test(lines[0]);
      if(hasHeader)lines=lines.slice(1);
      const numericList=!hasHeader&&lines.every(line=>line.split(/[\s,;]+/).every(v=>decimal.test(v)));
      if(numericList)rows=lines.join(' ').split(/[\s,;]+/).map((v,i)=>({id:String(i+1),balance:Number(v)}));
      else rows=lines.map((line,i)=>{
        const parts=line.split(/[,\t]/).map(s=>s.trim());
        if(parts.length!==2||!parts[0]||!decimal.test(parts[1]))throw Error('Line '+(i+1)+': use wallet,balance, or paste numbers without thousands separators.');
        return {id:parts[0],balance:Number(parts[1])};
      });
    }
    if(rows.length>MAX_HOLDER_BALANCES)throw Error('This local study accepts up to '+MAX_HOLDER_BALANCES+' balances. Nothing was applied.');
    const ids=new Set();
    rows=rows.map((row,i)=>{
      if(!row||typeof row!=='object')throw Error('Record '+(i+1)+': supply an id and a numeric balance.');
      const id=String(row.id??row.address??row.wallet??i+1).trim();
      const balance=typeof row.balance==='string'&&decimal.test(row.balance.trim())?Number(row.balance):row.balance;
      if(!finite(balance)||balance<0)throw Error('Record '+(i+1)+': balances must be finite, nonnegative numbers.');
      if(!id||id.length>512)throw Error('Record '+(i+1)+': use a nonempty holder identifier of up to 512 characters.');
      if(ids.has(id))throw Error('Duplicate holder identifier: '+id+'. Combine that holder’s balance into one row.');
      ids.add(id);return {id,balance};
    });
    return {balances:normalizeHolderBalances(rows),error:''};
  }catch(error){return {balances:[],error:error instanceof SyntaxError?'The JSON could not be read. Use an array of balances or {id, balance} records.':error.message};}
}

export function deriveFieldRules(inputs={}){
  const capKnown=finite(inputs.marketCap)&&inputs.marketCap>0;
  const liquidityKnown=finite(inputs.liquidity)&&inputs.liquidity>=0;
  const marketCap=capKnown?inputs.marketCap:1e6;
  const liquidity=liquidityKnown?inputs.liquidity:0;
  // Calibration: $100..$1B for spacing, $1..$50M for gradual field
  // opening, and $0..$10M liquidity for the base mark diameter.
  // These bounded ranges are separate from the permanent mapping directions.
  const capDepth=capKnown?clamp((Math.log10(marketCap)-2)/7,0,1):.5;
  const gapPx=Math.ceil(16-12*capDepth);
  // Release the spatial fade over the existing artwork interval, so the
  // full image is available at $50M. This does not change image attraction.
  const fieldRelease=capKnown?smoothstep(Math.log10(marketCap/1e7)/Math.log10(5)):1;
  const edgeShrink=(.02+.46*(1-capDepth**2))*(1-fieldRelease);
  const edgePower=1+3*(1-capDepth)**2;
  // A fourth-power curve keeps $3K near 6% opening, rather than fully
  // opening the field at $100. Span is a falloff scale, not a shape boundary.
  const emergence=clamp(Math.log10(marketCap)/Math.log10(50e6),0,1);
  const fieldSpan=capKnown?.02+.98*emergence**4:1;
  const liquidityDepth=clamp(Math.log10(1+liquidity/1000)/4,0,1);
  // Missing live values use explicit neutral geometry, never simulated data.
  const baseMarkSize=liquidityKnown?2+14*liquidityDepth:6;
  const balances=normalizeHolderBalances(inputs.holderBalances);
  // Divide by the maximum before summing to avoid overflow for large units.
  // Area is proportional to each supplied balance, subject to raster floors.
  const maximum=balances.length?Math.max(...balances.map(h=>h.balance)):1;
  const relative=balances.length?balances.map(h=>h.balance/maximum):[1];
  const mean=relative.reduce((a,b)=>a+b,0)/relative.length;
  const multipliers=relative.map(v=>Math.sqrt(v/mean));
  // Normalize holder multipliers independently of liquidity. A three-times
  // base maximum gives a 48px ceiling at full liquidity, without cancelling
  // liquidity growth for concentrated distributions. Ratios remain intact
  // before the final one-pixel (three-pixel for +/×) raster minimum.
  const footprintScale=Math.min(1,3/Math.max(...multipliers));
  const markDiameters=multipliers.map(v=>baseMarkSize*v*footprintScale);
  return {gapPx,edgeShrink,edgePower,fieldSpan,fieldRelease,baseMarkSize,markDiameters,footprintScale,
    holderCount:balances.length,holderStatus:balances.length?balances.length+(inputs.holderSource==='simulated'?' simulated balances · example distribution':' supplied holder balances'):'No holder balances supplied — equal mark sizes',
    capDepth,liquidityDepth,balances};
}

function smoothstep(value){const t=clamp(value,0,1);return t*t*(3-2*t);}
function hash(text){let value=2166136261;for(const c of text)value=Math.imul(value^c.charCodeAt(0),16777619);return value>>>0;}

// Smooth spatial noise for the shrink envelope only. The seed and sampling
// coordinates never depend on time, cap, liquidity or holder balances.
function fieldNoise(x,y,seed){
  const ix=Math.floor(x),iy=Math.floor(y),tx=smoothstep(x-ix),ty=smoothstep(y-iy);
  const sample=(a,b)=>{
    let n=seed^Math.imul(a,0x1f123bb5)^Math.imul(b,0x5f356495);
    n=Math.imul(n^(n>>>16),0x7feb352d);
    n=Math.imul(n^(n>>>15),0x846ca68b);
    return ((n^(n>>>16))>>>0)/4294967295;
  };
  const a=sample(ix,iy),b=sample(ix+1,iy),c=sample(ix,iy+1),d=sample(ix+1,iy+1);
  return (a+(b-a)*tx)*(1-ty)+(c+(d-c)*tx)*ty;
}

/** Rows pack actual mark bounds, with a minimum clear edge gap in both axes.
 * Horizontal neighboring bounds have the exact integer gap; shorter marks
 * in neighboring rows and hidden marks can leave larger gaps. The field
 * repeats the supplied distribution; no wallet-count claim is made.
 */
export function buildMarkLayout(inputs,settings={},width=512,height=512){
  const rules=deriveFieldRules(inputs),gap=rules.gapPx;
  const shape=settings.mode==='monogrid'?'square':settings.mark||'auto';
  const directional=shape==='plus'||shape==='cross'||(shape==='auto'&&inputs.change!==0);
  const minimum=directional?3:1;
  const order=rules.markDiameters.map((size,i)=>({size,id:rules.balances[i]?.id||'equal'}))
    .sort((a,b)=>hash(inputs.coinKey+':'+a.id)-hash(inputs.coinKey+':'+b.id)||a.id.localeCompare(b.id));
  const rasterSize=size=>directional?Math.max(3,2*Math.floor((size-1)/2)+1):Math.max(1,Math.round(size));
  const marks=[];
  // Reserve slots across the canvas; fade individual marks instead of
  // cutting the field to a circular, rounded-box or rectangular outline.
  const left=0,right=width,top=0,bottom=height;
  const seed=hash(String(inputs.coinKey||'upic:field'));
  const centerX=.5+((seed&65535)/65535-.5)*.035;
  const centerY=.5+((seed>>>16)/65535-.5)*.035;
  const taperAt=(x,y)=>{
    if(rules.fieldRelease===1)return 1;
    const nx=(x/width-centerX)*2,ny=(y/height-centerY)*2;
    // Warping and uneven thresholds break symmetry. Fixed canvas-space
    // noise lets increasing cap open the same fade instead of regenerating it.
    const wx=nx+.26*(fieldNoise(nx*3.1,ny*3.1,seed^0x68bc21eb)-.5);
    const wy=ny+.26*(fieldNoise(nx*3.1,ny*3.1,seed^0x02e5be93)-.5);
    const distance=(wx*wx+wy*wy)/(rules.fieldSpan*rules.fieldSpan);
    // Relax the spatial fade itself. Adding release to every diameter made
    // all outer slots cross the one-pixel visibility floor at the same cap
    // (about $14M for a 9px nominal mark), creating a sudden field-wide jump.
    const remainingShrink=1-rules.fieldRelease;
    const envelope=Math.exp(-(1+rules.edgeShrink)*distance*remainingShrink);
    const breakup=.6*fieldNoise(nx*7,ny*7,seed^0x967a889b)
      +.4*fieldNoise(nx*19,ny*19,seed^0x368cc8b7);
    const cutoff=(.04+.5*breakup)*remainingShrink;
    const fade=smoothstep((envelope-cutoff)/.3)**(rules.edgePower/2);
    // Near zero cap, even the central marks remain tiny at high liquidity.
    const tinyCapScale=Math.min(1,rules.fieldSpan/.12);
    return fade*tinyCapScale;
  };
  let index=0,row=0,y=top;
  while(y+minimum<=bottom){
    const entries=[];let x=left,maxHeight=minimum;
    // Probe the smallest reserved slot, then check the final mark center.
    const probeY=Math.min(bottom-.5,y+minimum/2);
    while(x+minimum<=right){
      const holder=order[index%order.length];
      const probeX=Math.min(right-.5,x+minimum/2);
      const normalDiameter=rasterSize(holder.size);
      const taperedDiameter=normalDiameter*taperAt(probeX,probeY);
      const diameter=rasterSize(taperedDiameter);
      if(x+diameter>right)break;
      // Keep the slot and gap even when the mark shrinks below one pixel.
      // Otherwise the 3px +/× floor repopulates every edge with tiny glyphs.
      entries.push({x:x+diameter/2,diameter,normalDiameter,id:holder.id,column:entries.length});
      maxHeight=Math.max(maxHeight,diameter);x+=diameter+gap;index++;
    }
    if(!entries.length||y+maxHeight>bottom)break;
    for(const entry of entries){
      const centreY=y+Math.floor((maxHeight-entry.diameter)/2)+entry.diameter/2;
      const actualDiameter=entry.normalDiameter*taperAt(entry.x,centreY);
      if(actualDiameter<1)continue;
      // Check the final center too, then only shrink inside the reserved slot.
      // The fade never pushes a mark into the required empty gap.
      const diameter=Math.min(entry.diameter,rasterSize(actualDiameter));
      marks.push({...entry,diameter,y:centreY,row});
    }
    y+=maxHeight+gap;row++;
  }
  return {marks,rules};
}
